template <class W = int> class ngraph_list {
    vector<vector<narc<W>>> adjacency_;
    int arcs_ = 0;

    static size_t checked_vertices(int vertices) {
        npre(vertices >= 0);
        return size_t(vertices);
    }

  public:
    explicit ngraph_list(int vertices = 0) : adjacency_(checked_vertices(vertices)) {}

    int vertices() const noexcept { return int(adjacency_.size()); }
    int arcs() const noexcept { return arcs_; }

    void add(int from, int to, W weight = W{1}) {
        npre(0 <= from && from < vertices() && 0 <= to && to < vertices());
        npre(arcs_ < INT_MAX);
        npre(adjacency_[from].size() < size_t(INT_MAX));
        adjacency_[from].push_back({to, move(weight)});
        ++arcs_;
    }
    void add2(int a, int b, const W& weight = W{1}) {
        add(a, b, weight);
        add(b, a, weight);
    }

    nspan<const narc<W>> neighbors(int vertex) const {
        npre(0 <= vertex && vertex < vertices());
        const auto& edges = adjacency_[vertex];
        npre(edges.size() <= size_t(INT_MAX));
        return {edges.data(), int(edges.size())};
    }
};

template <ngraph_like G> nvector<int> nbfs(const G& graph, int source) {
    int vertices = ni::ngraph_vertices(graph);
    npre(0 <= source && source < vertices);
    nvector<int> distance(vertices, npos);
    ndeque<int> queue;
    distance[source] = 0;
    queue.pushr(source);
    while (!queue.empty()) {
        int vertex = queue.popl();
        decltype(auto) adjacency = graph.neighbors(vertex);
        nfor(edge, adjacency) {
            int to = nedge_to(edge);
            npre(0 <= to && to < vertices);
            if (distance[to] == npos) {
                distance[to] = distance[vertex] + 1;
                queue.pushr(to);
            }
        }
    }
    return distance;
}

template <class D = long long, ngraph_like G>
    requires is_arithmetic_v<D> && (!same_as<remove_cv_t<D>, bool>)
nvector<D> ndijkstra(const G& graph, int source, D infinity = nmin<D>{}.id()) {
    int vertices = ni::ngraph_vertices(graph);
    npre(0 <= source && source < vertices);
    npre(D{} <= infinity);
    nvector<D> distance(vertices, infinity);
    using state = pair<D, int>;
    priority_queue<state, vector<state>, greater<state>> queue;
    distance[source] = D{};
    queue.push({D{}, source});

    while (!queue.empty()) {
        auto [current, vertex] = queue.top();
        queue.pop();
        if (current != distance[vertex])
            continue;
        decltype(auto) adjacency = graph.neighbors(vertex);
        nfor(edge, adjacency) {
            int to = nedge_to(edge);
            D weight = ni::nchecked_number<D>(nedge_weight(edge));
            npre(0 <= to && to < vertices);
            npre(!(weight < D{}));
            if (current <= infinity && weight <= infinity - current) {
                D candidate = current + weight;
                if (candidate < distance[to]) {
                    distance[to] = candidate;
                    queue.push({candidate, to});
                }
            }
        }
    }
    return distance;
}

// ---- 41_graph_alg.hpp ----
template <ngraph_like G> nmaybe<nvector<int>> ntoposort(const G& graph) {
    int vertices = ni::ngraph_vertices(graph);
    nvector<int> indegree(vertices, 0);
    for (int from = 0; from < vertices; ++from) {
        decltype(auto) adjacency = graph.neighbors(from);
        nfor(edge, adjacency) {
            int to = nedge_to(edge);
            npre(0 <= to && to < vertices);
            npre(indegree[to] < INT_MAX);
            ++indegree[to];
        }
    }

    ndeque<int> queue;
    for (int vertex = 0; vertex < vertices; ++vertex)
        if (indegree[vertex] == 0)
            queue.pushr(vertex);

    nvector<int> order;
    order.reserve(vertices);
    while (!queue.empty()) {
        int from = queue.popl();
        order.push(from);
        decltype(auto) adjacency = graph.neighbors(from);
        nfor(edge, adjacency) {
            int to = nedge_to(edge);
            if (--indegree[to] == 0)
                queue.pushr(to);
        }
    }
    return order.len() == vertices ? nmaybe<nvector<int>>(move(order)) : nmaybe<nvector<int>>{};
}

template <ngraph_like G> npartition nscc(const G& graph) {
    int vertices = ni::ngraph_vertices(graph);
    auto forward = vector<vector<int>>(size_t(vertices));
    auto reverse = vector<vector<int>>(size_t(vertices));
    for (int from = 0; from < vertices; ++from) {
        decltype(auto) adjacency = graph.neighbors(from);
        nfor(edge, adjacency) {
            int to = nedge_to(edge);
            npre(0 <= to && to < vertices);
            npre(forward[from].size() < size_t(INT_MAX));
            npre(reverse[to].size() < size_t(INT_MAX));
            forward[from].push_back(to);
            reverse[to].push_back(from);
        }
    }

    vector<unsigned char> seen(size_t(vertices), false);
    vector<int> order;
    order.reserve(size_t(vertices));
    for (int start = 0; start < vertices; ++start) {
        if (seen[start])
            continue;
        seen[start] = true;
        vector<pair<int, int>> stack{{start, 0}};
        while (!stack.empty()) {
            int vertex = stack.back().first;
            int& position = stack.back().second;
            if (position < int(forward[vertex].size())) {
                int to = forward[vertex][position++];
                if (!seen[to]) {
                    seen[to] = true;
                    stack.push_back({to, 0});
                }
            } else {
                order.push_back(vertex);
                stack.pop_back();
            }
        }
    }

    nvector<int> component(vertices, npos);
    int count = 0;
    for (int position = vertices; position-- > 0;) {
        int start = order[position];
        if (component[start] != npos)
            continue;
        component[start] = count;
        vector<int> stack{start};
        while (!stack.empty()) {
            int vertex = stack.back();
            stack.pop_back();
            for (int to : reverse[vertex])
                if (component[to] == npos) {
                    component[to] = count;
                    stack.push_back(to);
                }
        }
        ++count;
    }
    return npartition(move(component));
}

namespace ni {
struct ntree_layout {
    vector<vector<int>> adjacency;
    nvector<int> parent, order;
};

template <ngraph_like G>
ntree_layout nbuild_tree_layout(const G& graph, int root, bool require_symmetric) {
    int vertices = ngraph_vertices(graph);
    npre(vertices > 0 && 0 <= root && root < vertices);
    ntree_layout result{vector<vector<int>>(size_t(vertices)), nvector<int>(vertices, npos), {}};

    for (int from = 0; from < vertices; ++from) {
        decltype(auto) edges = graph.neighbors(from);
        nfor(edge, edges) {
            int to = nedge_to(edge);
            npre(0 <= to && to < vertices && to != from);
            npre(result.adjacency[from].size() < size_t(INT_MAX));
            result.adjacency[from].push_back(to);
        }
    }

    result.order.reserve(vertices);
    result.parent[root] = root;
    result.order.push(root);
    for (int position = 0; position < result.order.len(); ++position) {
        int from = result.order[position];
        for (int to : result.adjacency[from])
            if (result.parent[to] == npos) {
                result.parent[to] = from;
                result.order.push(to);
            }
    }
    npre(result.order.len() == vertices);

    long long forward_arcs = 0, reverse_arcs = 0;
    for (int from = 0; from < vertices; ++from)
        for (int to : result.adjacency[from]) {
            if (result.parent[to] == from)
                ++forward_arcs;
            else if (from != root && to == result.parent[from])
                ++reverse_arcs;
            else
                npre(false);
        }
    npre(forward_arcs == vertices - 1LL);
    if (require_symmetric)
        npre(reverse_arcs == vertices - 1LL);
    else
        npre(reverse_arcs == 0 || reverse_arcs == vertices - 1LL);
    return result;
}
} // namespace ni

class nlca {
    int vertices_ = 0;
    vector<vector<int>> ancestor_;
    nvector<int> depth_;

  public:
    nlca() = default;

    template <ngraph_like G> explicit nlca(const G& graph, int root = 0)
        : vertices_(ni::ngraph_vertices(graph)), depth_(vertices_, npos) {
        auto layout = ni::nbuild_tree_layout(graph, root, false);
        int levels = max(1, int(bit_width(unsigned(vertices_))));
        ancestor_.assign(size_t(levels), vector<int>(size_t(vertices_), root));
        depth_[root] = 0;
        ancestor_[0][root] = root;
        for (int position = 1; position < layout.order.len(); ++position) {
            int vertex = layout.order[position], parent = layout.parent[vertex];
            depth_[vertex] = depth_[parent] + 1;
            ancestor_[0][vertex] = parent;
        }
        for (int level = 1; level < levels; ++level)
            for (int vertex = 0; vertex < vertices_; ++vertex)
                ancestor_[level][vertex] = ancestor_[level - 1][ancestor_[level - 1][vertex]];
    }

    int len() const noexcept { return vertices_; }
    int depth(int vertex) const {
        npre(0 <= vertex && vertex < vertices_);
        return depth_[vertex];
    }

    int jump(int vertex, int steps) const {
        npre(0 <= vertex && vertex < vertices_ && steps >= 0);
        if (steps > depth_[vertex])
            return npos;
        for (int level = 0; steps; ++level, steps >>= 1)
            if (steps & 1)
                vertex = ancestor_[level][vertex];
        return vertex;
    }

    int operator()(int a, int b) const {
        npre(0 <= a && a < vertices_ && 0 <= b && b < vertices_);
        if (depth_[a] < depth_[b])
            swap(a, b);
        a = jump(a, depth_[a] - depth_[b]);
        if (a == b)
            return a;
        for (int level = int(ancestor_.size()); level-- > 0;)
            if (ancestor_[level][a] != ancestor_[level][b]) {
                a = ancestor_[level][a];
                b = ancestor_[level][b];
            }
        return ancestor_[0][a];
    }

    int distance(int a, int b) const {
        int common = (*this)(a, b);
        long long result = 1LL * depth_[a] + depth_[b] - 2LL * depth_[common];
        npre(0 <= result && result <= INT_MAX);
        return int(result);
    }

    int kth_on_path(int from, int to, int steps) const {
        npre(steps >= 0);
        int common = (*this)(from, to);
        int upward = depth_[from] - depth_[common];
        int downward = depth_[to] - depth_[common];
        long long length = 1LL * upward + downward;
        if (steps > length)
            return npos;
        return steps <= upward ? jump(from, steps) : jump(to, int(length - steps));
    }
};

// ---- 42_tree.hpp ----
template <ngraph_like G, class T, class Merge, class Vertex, class Lift>
    requires copyable<T>
nvector<T> nreroot(const G& graph, T identity, Merge merge, Vertex vertex, Lift lift, int root = 0) {
    int vertices = ni::ngraph_vertices(graph);
    if (!vertices)
        return {};
    auto layout = ni::nbuild_tree_layout(graph, root, true);
    auto& adjacency = layout.adjacency;
    auto& parent = layout.parent;
    auto& order = layout.order;

    nvector<T> down(vertices, identity), upward(vertices, identity), answer(vertices, identity);
    for (int position = vertices; position-- > 0;) {
        int from = order[position];
        T aggregate = identity;
        for (int to : adjacency[from])
            if (parent[to] == from)
                aggregate = invoke(merge, move(aggregate), invoke(lift, down[to], to, from));
        down[from] = invoke(vertex, move(aggregate), from);
    }

    for (int position = 0; position < vertices; ++position) {
        int from = order[position];
        int degree = int(adjacency[from].size());
        nvector<T> contribution;
        contribution.reserve(degree);
        for (int to : adjacency[from])
            contribution.push(to == parent[from] ? upward[from] : invoke(lift, down[to], to, from));

        nvector<T> prefix(degree + 1, identity), suffix(degree + 1, identity);
        for (int i = 0; i < degree; ++i)
            prefix[i + 1] = invoke(merge, prefix[i], contribution[i]);
        for (int i = degree; i-- > 0;)
            suffix[i] = invoke(merge, contribution[i], suffix[i + 1]);
        answer[from] = invoke(vertex, prefix[degree], from);

        for (int i = 0; i < degree; ++i) {
            int to = adjacency[from][i];
            if (parent[to] != from)
                continue;
            T without_child = invoke(merge, prefix[i], suffix[i + 1]);
            upward[to] = invoke(lift, invoke(vertex, move(without_child), from), from, to);
        }
    }
    return answer;
}

// ---- 43_graph_more.hpp ----
template <ngraph_like G> nvector<int> n01bfs(const G& graph, int source) {
    int vertices = ni::ngraph_vertices(graph);
    npre(0 <= source && source < vertices);
    nvector<int> distance(vertices, npos);
    ndeque<int> queue;
    distance[source] = 0;
    queue.pushr(source);
    while (!queue.empty()) {
        int from = queue.popl();
        decltype(auto) adjacency = graph.neighbors(from);
        nfor(edge, adjacency) {
            int to = nedge_to(edge);
            auto&& raw_weight = nedge_weight(edge);
            npre(raw_weight == 0 || raw_weight == 1);
            int weight = int(raw_weight);
            npre(0 <= to && to < vertices);
            int candidate = distance[from] + weight;
            if (distance[to] == npos || candidate < distance[to]) {
                distance[to] = candidate;
                weight ? queue.pushr(to) : queue.pushl(to);
            }
        }
    }
    return distance;
}

template <class W> struct nmst_result {
    W weight{};
    nvector<pair<int, int>> edges;
};

template <class D = long long, ngraph_like G>
    requires is_arithmetic_v<D> && (!same_as<remove_cv_t<D>, bool>)
nmaybe<nmst_result<D>> nprim(const G& graph, int root = 0) {
    int vertices = ni::ngraph_vertices(graph);
    if (!vertices)
        return nmst_result<D>{};
    npre(0 <= root && root < vertices);
    using candidate = tuple<D, int, int>;
    priority_queue<candidate, vector<candidate>, greater<candidate>> queue;
    nvector<unsigned char> used(vertices, false);
    nmst_result<D> result;
    result.edges.reserve(vertices - 1);
    queue.push({D{}, root, npos});
    int visited = 0;
    while (!queue.empty()) {
        auto [weight, vertex, parent] = queue.top();
        queue.pop();
        if (used[vertex])
            continue;
        used[vertex] = true;
        ++visited;
        if (parent != npos) {
            result.weight = ni::nchecked_add(result.weight, weight);
            result.edges.push(pair<int, int>{parent, vertex});
        }
        decltype(auto) adjacency = graph.neighbors(vertex);
        nfor(edge, adjacency) {
            int to = nedge_to(edge);
            npre(0 <= to && to < vertices);
            if (!used[to])
                queue.push({ni::nchecked_number<D>(nedge_weight(edge)), to, vertex});
        }
    }
    return visited == vertices ? nmaybe<nmst_result<D>>(move(result)) : nmaybe<nmst_result<D>>{};
}

template <class C>
    requires integral<C> && (!same_as<remove_cv_t<C>, bool>)
class nmaxflow {
    struct edge {
        int to, reverse;
        C capacity;
    };
    vector<vector<edge>> graph_;
    bool flowed_ = false;

    static size_t checked_vertices(int vertices) {
        npre(0 <= vertices && vertices <= INT_MAX / 2);
        return size_t(vertices);
    }

  public:
    explicit nmaxflow(int vertices = 0) : graph_(checked_vertices(vertices)) {}
    int vertices() const noexcept { return int(graph_.size()); }

    void add(int from, int to, C capacity) {
        npre(!flowed_);
        npre(0 <= from && from < vertices() && 0 <= to && to < vertices() && from != to);
        npre(!(capacity < C{}));
        npre(graph_[to].size() < size_t(INT_MAX) && graph_[from].size() < size_t(INT_MAX));
        int from_reverse = int(graph_[to].size());
        int to_reverse = int(graph_[from].size());
        graph_[from].push_back({to, from_reverse, capacity});
        graph_[to].push_back({from, to_reverse, C{}});
    }

    C flow(int source, int sink) {
        npre(!flowed_);
        npre(0 <= source && source < vertices() && 0 <= sink && sink < vertices() && source != sink);
        flowed_ = true;
        int n = vertices();
        vector<int> height(size_t(n), 0), current(size_t(n), 0);
        vector<C> excess(size_t(n), C{});
        vector<unsigned char> queued(size_t(n), false);
        deque<int> active;

        auto activate = [&](int vertex) {
            if (vertex != source && vertex != sink && !queued[vertex] && C{} < excess[vertex]) {
                queued[vertex] = true;
                active.push_back(vertex);
            }
        };
        auto push = [&](int from, edge& arc) {
            C sent = min(excess[from], arc.capacity);
            if (!(C{} < sent) || height[from] != height[arc.to] + 1)
                return false;
            npre(graph_[arc.to][arc.reverse].capacity <= numeric_limits<C>::max() - sent);
            npre(excess[arc.to] <= numeric_limits<C>::max() - sent);
            arc.capacity -= sent;
            graph_[arc.to][arc.reverse].capacity += sent;
            excess[from] -= sent;
            excess[arc.to] += sent;
            activate(arc.to);
            return true;
        };

        height[source] = n;
        for (edge& arc : graph_[source]) {
            C sent = arc.capacity;
            if (!(C{} < sent))
                continue;
            npre(graph_[arc.to][arc.reverse].capacity <= numeric_limits<C>::max() - sent);
            npre(excess[arc.to] <= numeric_limits<C>::max() - sent);
            arc.capacity = C{};
            graph_[arc.to][arc.reverse].capacity += sent;
            excess[arc.to] += sent;
            activate(arc.to);
        }

        while (!active.empty()) {
            int vertex = active.front();
            active.pop_front();
            queued[vertex] = false;
            while (C{} < excess[vertex]) {
                if (current[vertex] == int(graph_[vertex].size())) {
                    int next_height = 2 * n;
                    for (const edge& arc : graph_[vertex])
                        if (C{} < arc.capacity)
                            nchmin(next_height, height[arc.to] + 1);
                    npre(next_height < 2 * n);
                    height[vertex] = next_height;
                    current[vertex] = 0;
                    continue;
                }
                edge& arc = graph_[vertex][current[vertex]];
                if (!push(vertex, arc))
                    ++current[vertex];
            }
        }
        return excess[sink];
    }

    nvector<unsigned char> mincut(int source) const {
        npre(flowed_ && 0 <= source && source < vertices());
        nvector<unsigned char> reachable(vertices(), false);
        ndeque<int> queue;
        reachable[source] = true;
        queue.pushr(source);
        while (!queue.empty()) {
            int from = queue.popl();
            for (const edge& arc : graph_[from])
                if (C{} < arc.capacity && !reachable[arc.to]) {
                    reachable[arc.to] = true;
                    queue.pushr(arc.to);
                }
        }
        return reachable;
    }
};

// ---- 44_matching.hpp ----
struct nbipartite_matching {
    int size = 0;
    nvector<int> left, right;
};

template <ngraph_like G> nbipartite_matching nhopcroft_karp(const G& graph, int right_vertices) {
    int left_vertices = ni::ngraph_vertices(graph);
    npre(right_vertices >= 0);
    nvector<nvector<int>> adjacency(left_vertices);
    for (int left = 0; left < left_vertices; ++left) {
        decltype(auto) edges = graph.neighbors(left);
        nfor(edge, edges) {
            int right = nedge_to(edge);
            npre(0 <= right && right < right_vertices);
            adjacency[left].push(right);
        }
    }

    nbipartite_matching result{0, nvector<int>(left_vertices, npos), nvector<int>(right_vertices, npos)};
    nvector<int> distance(left_vertices), next(left_vertices);
    for (;;) {
        for (int left = 0; left < left_vertices; ++left)
            distance[left] = npos;
        ndeque<int> queue;
        for (int left = 0; left < left_vertices; ++left)
            if (result.left[left] == npos) {
                distance[left] = 0;
                queue.pushr(left);
            }
        long long shortest = numeric_limits<long long>::max();
        while (!queue.empty()) {
            int left = queue.popl();
            if (distance[left] + 1 > shortest)
                continue;
            for (int i = 0; i < adjacency[left].len(); ++i) {
                int right = adjacency[left][i], next_left = result.right[right];
                if (next_left == npos)
                    nchmin(shortest, distance[left] + 1);
                else if (distance[next_left] == npos && distance[left] + 1 < shortest) {
                    distance[next_left] = distance[left] + 1;
                    queue.pushr(next_left);
                }
            }
        }
        if (shortest == numeric_limits<long long>::max())
            break;
        for (int left = 0; left < left_vertices; ++left)
            next[left] = 0;
        int augmented = 0;
        for (int root = 0; root < left_vertices; ++root) {
            if (result.left[root] != npos || distance[root] != 0)
                continue;
            nvector<int> stack{root}, via_right{npos};
            bool found = false;
            while (!stack.empty() && !found) {
                int left = stack.back();
                while (next[left] < adjacency[left].len()) {
                    int right = adjacency[left][next[left]++];
                    int next_left = result.right[right];
                    if (next_left == npos) {
                        if (distance[left] + 1 != shortest)
                            continue;
                        result.left[left] = right;
                        result.right[right] = left;
                        for (int depth = stack.len() - 1; depth > 0; --depth) {
                            int parent = stack[depth - 1], parent_right = via_right[depth];
                            result.left[parent] = parent_right;
                            result.right[parent_right] = parent;
                        }
                        found = true;
                        ++augmented;
                        break;
                    }
                    if (distance[next_left] == distance[left] + 1) {
                        stack.push(next_left);
                        via_right.push(right);
                        break;
                    }
                }
                if (!found && !stack.empty() && next[stack.back()] == adjacency[stack.back()].len()) {
                    distance[stack.back()] = npos;
                    stack.pop();
                    via_right.pop();
                }
            }
        }
        if (!augmented)
            break;
        result.size += augmented;
    }
    return result;
}

// ---- 50_integer.hpp ----
template <class T>
concept ninteger = integral<T> && (!same_as<remove_cv_t<T>, bool>);

template <ninteger T> constexpr make_unsigned_t<T> nmag(T value) {
    using U = make_unsigned_t<T>;
    U encoded = U(value);
    if constexpr (is_signed_v<T>)
        return value < 0 ? U{} - encoded : encoded;
    else
        return encoded;
}

template <ninteger T> constexpr make_unsigned_t<T> nabs(T value) { return nmag(value); }

template <ninteger T> constexpr make_unsigned_t<T> ngcd(T a, T b) {
    using U = make_unsigned_t<T>;
    U x = nmag(a), y = nmag(b);
    while (y) {
        U remainder = x % y;
        x = y;
        y = remainder;
    }
    return x;
}

template <ninteger T> constexpr make_unsigned_t<T> nlcm(T a, T b) {
    using U = make_unsigned_t<T>;
    U x = nmag(a), y = nmag(b);
    if (!x || !y)
        return 0;
    U divisor = ngcd(a, b);
    npre(x / divisor <= numeric_limits<U>::max() / y);
    return x / divisor * y;
}

template <signed_integral T> constexpr T nfloor_div(T a, T b) {
    npre(b != 0);
    npre(!(a == numeric_limits<T>::lowest() && b == T(-1)));
    T quotient = a / b, remainder = a % b;
    if (remainder && ((remainder < 0) != (b < 0)))
        --quotient;
    return quotient;
}

template <signed_integral T> constexpr T nceil_div(T a, T b) {
    npre(b != 0);
    npre(!(a == numeric_limits<T>::lowest() && b == T(-1)));
    T quotient = a / b, remainder = a % b;
    if (remainder && ((remainder < 0) == (b < 0)))
        ++quotient;
    return quotient;
}

template <signed_integral T> constexpr T nmod(T value, T modulus) {
    npre(modulus > 0);
    T remainder = value % modulus;
    return remainder < 0 ? remainder + modulus : remainder;
}

template <ninteger T>
    requires(sizeof(T) <= sizeof(uint64_t))
struct nextgcd_result {
    make_unsigned_t<T> gcd;
    __int128_t x, y;
};

template <ninteger T>
    requires(sizeof(T) <= sizeof(uint64_t))
constexpr nextgcd_result<T> nextgcd(T a, T b) {
    using U = make_unsigned_t<T>;
    U old_remainder = nmag(a), remainder = nmag(b);
    __int128_t old_x = 1, x = 0, old_y = 0, y = 1;
    while (remainder) {
        U quotient = old_remainder / remainder;
        U next_remainder = old_remainder % remainder;
        old_remainder = remainder;
        remainder = next_remainder;
        __int128_t next_x = old_x - __int128_t(quotient) * x;
        __int128_t next_y = old_y - __int128_t(quotient) * y;
        old_x = x;
        x = next_x;
        old_y = y;
        y = next_y;
    }
    if constexpr (is_signed_v<T>) {
        if (a < 0)
            old_x = -old_x;
        if (b < 0)
            old_y = -old_y;
    }
    return {old_remainder, old_x, old_y};
}

constexpr uint64_t nmulmod(uint64_t a, uint64_t b, uint64_t modulus) {
    npre(modulus > 0);
    return uint64_t(__uint128_t(a) * b % modulus);
}

constexpr uint64_t npowmod(uint64_t base, uint64_t exponent, uint64_t modulus) {
    npre(modulus > 0);
    uint64_t result = 1 % modulus;
    base %= modulus;
    while (exponent) {
        if (exponent & 1)
            result = nmulmod(result, base, modulus);
        exponent >>= 1;
        if (exponent)
            base = nmulmod(base, base, modulus);
    }
    return result;
}

constexpr bool nisprime(uint64_t value) {
    if (value < 2)
        return false;
    for (uint64_t prime : {2ULL, 3ULL, 5ULL, 7ULL, 11ULL, 13ULL, 17ULL, 19ULL, 23ULL, 29ULL, 31ULL, 37ULL}) {
        if (value % prime == 0)
            return value == prime;
    }
    uint64_t odd = value - 1;
    int shifts = countr_zero(odd);
    odd >>= shifts;
    for (uint64_t base : {2ULL, 325ULL, 9375ULL, 28178ULL, 450775ULL, 9780504ULL, 1795265022ULL}) {
        if (base % value == 0)
            continue;
        uint64_t witness = npowmod(base, odd, value);
        if (witness == 1 || witness == value - 1)
            continue;
        bool composite = true;
        for (int round = 1; round < shifts; ++round) {
            witness = nmulmod(witness, witness, value);
            if (witness == value - 1) {
                composite = false;
                break;
            }
        }
        if (composite)
            return false;
    }
    return true;
}

inline nvector<int> nprimes(int limit) {
    npre(0 <= limit && limit < INT_MAX);
    nvector<int> primes, least(limit + 1, 0);
    for (int value = 2; value <= limit; ++value) {
        if (!least[value]) {
            least[value] = value;
            primes.push(value);
        }
        for (int index = 0; index < primes.len(); ++index) {
            int prime = primes[index];
            if (prime > least[value] || 1LL * value * prime > limit)
                break;
            least[value * prime] = prime;
        }
    }
    return primes;
}

// ---- 51_modular.hpp ----
template <uint64_t Modulus>
    requires(Modulus > 1)
class nmodint {
    uint64_t value_ = 0;

    template <integral I> static constexpr uint64_t normalize(I value) {
        if constexpr (is_signed_v<I>) {
            __int128_t remainder = __int128_t(value) % __int128_t(Modulus);
            if (remainder < 0)
                remainder += Modulus;
            return uint64_t(remainder);
        } else {
            return uint64_t(__uint128_t(value) % Modulus);
        }
    }

  public:
    static constexpr uint64_t mod() noexcept { return Modulus; }
    constexpr nmodint() = default;
    template <integral I> constexpr nmodint(I value) : value_(normalize(value)) {}

    constexpr uint64_t val() const noexcept { return value_; }

    constexpr nmodint& operator+=(nmodint other) {
        __uint128_t sum = __uint128_t(value_) + other.value_;
        value_ = uint64_t(sum >= Modulus ? sum - Modulus : sum);
        return *this;
    }
    constexpr nmodint& operator-=(nmodint other) {
        value_ = value_ >= other.value_ ? value_ - other.value_ : Modulus - (other.value_ - value_);
        return *this;
    }
    constexpr nmodint& operator*=(nmodint other) {
        value_ = nmulmod(value_, other.value_, Modulus);
        return *this;
    }

    constexpr nmodint pow(uint64_t exponent) const { return nmodint::raw(npowmod(value_, exponent, Modulus)); }

    constexpr nmaybe<nmodint> inverse() const {
        if (!value_)
            return {};
        __int128_t old_remainder = Modulus, remainder = value_;
        __int128_t old_coefficient = 0, coefficient = 1;
        while (remainder) {
            __int128_t quotient = old_remainder / remainder;
            tie(old_remainder, remainder) = pair{remainder, old_remainder - quotient * remainder};
            tie(old_coefficient, coefficient) =
                pair{coefficient, old_coefficient - quotient * coefficient};
        }
        if (old_remainder != 1)
            return {};
        old_coefficient %= __int128_t(Modulus);
        if (old_coefficient < 0)
            old_coefficient += Modulus;
        return raw(uint64_t(old_coefficient));
    }

    constexpr nmodint& operator/=(nmodint other) {
        auto inverse = other.inverse();
        npre(inverse.ok());
        return *this *= inverse.val();
    }

    constexpr nmodint operator+() const { return *this; }
    constexpr nmodint operator-() const { return value_ ? raw(Modulus - value_) : *this; }

    friend constexpr nmodint operator+(nmodint a, nmodint b) { return a += b; }
    friend constexpr nmodint operator-(nmodint a, nmodint b) { return a -= b; }
    friend constexpr nmodint operator*(nmodint a, nmodint b) { return a *= b; }
    friend constexpr nmodint operator/(nmodint a, nmodint b) { return a /= b; }
    friend constexpr bool operator==(nmodint, nmodint) = default;

    static constexpr nmodint raw(uint64_t value) {
        npre(value < Modulus);
        nmodint result;
        result.value_ = value;
        return result;
    }
};

template <uint64_t Modulus> inline constexpr bool nadd_group<nmodint<Modulus>> = true;
template <uint64_t Modulus> inline constexpr bool nexact_field<nmodint<Modulus>> = nisprime(Modulus);
template <uint64_t Modulus>
inline constexpr bool nsemiring_laws<nadd<nmodint<Modulus>>, nmul<nmodint<Modulus>>,
                                     nmodint<Modulus>> = true;
template <uint64_t Modulus>
inline constexpr bool naction_laws<naddsum_action<nmodint<Modulus>>, nmodint<Modulus>,
                                   nmodint<Modulus>> = true;

template <class Mint> class ncomb {
    nvector<Mint> factorial_, inverse_factorial_;

    static int checked_extent(int n) {
        npre(0 <= n && n < INT_MAX);
        return n + 1;
    }

  public:
    explicit ncomb(int n = 0) : factorial_(checked_extent(n)), inverse_factorial_(factorial_.len()) {
        factorial_[0] = Mint(1);
        for (int i = 1; i <= n; ++i)
            factorial_[i] = factorial_[i - 1] * Mint(i);
        auto inverse = factorial_[n].inverse();
        npre(inverse.ok());
        inverse_factorial_[n] = inverse.val();
        for (int i = n; i; --i)
            inverse_factorial_[i - 1] = inverse_factorial_[i] * Mint(i);
    }

    int len() const noexcept { return factorial_.len() - 1; }
    Mint factorial(int n) const {
        npre(0 <= n && n <= len());
        return factorial_[n];
    }
    Mint choose(int n, int k) const {
        npre(0 <= n && n <= len());
        if (k < 0 || n < k)
            return Mint{};
        return factorial_[n] * inverse_factorial_[k] * inverse_factorial_[n - k];
    }
    Mint permute(int n, int k) const {
        npre(0 <= n && n <= len());
        if (k < 0 || n < k)
            return Mint{};
        return factorial_[n] * inverse_factorial_[n - k];
    }
};

